1	/**
2	 * In-memory sample storage, one sorted bucket per series.
3	 *
4	 * Deliberately not durable: this is a bounded in-memory buffer over a recent
5	 * window — nothing is forwarded anywhere, and nothing reads it back.
6	 */
7	
8	import type { Sample } from "./validate.ts";
9	
10	export class MemoryStore {
11	  private readonly buckets = new Map<string, Sample[]>();
12	  private readonly maxPerSeries: number;
13	
14	  constructor(maxPerSeries: number) {
15	    if (!Number.isInteger(maxPerSeries) || maxPerSeries <= 0) {
16	      throw new RangeError("maxPerSeries must be a positive integer");
17	    }
18	    this.maxPerSeries = maxPerSeries;
19	  }
20	
21	  /** Insert a sample, keeping the series bucket ordered by timestamp. */
22	  put(sample: Sample): void {
23	    let bucket = this.buckets.get(sample.series);
24	    if (bucket === undefined) {
25	      bucket = [];
26	      this.buckets.set(sample.series, bucket);
27	    }
28	    const at = insertionPoint(bucket, sample.at);
29	    bucket.splice(at, 0, sample);
30	    if (bucket.length > this.maxPerSeries) {
31	      bucket.splice(0, bucket.length - this.maxPerSeries);
32	    }
33	  }
34	
35	  /** Samples for `series` with `from <= at < to`, in timestamp order. */
36	  range(series: string, from: number, to: number): Sample[] {
37	    const bucket = this.buckets.get(series);
38	    if (bucket === undefined) return [];
39	    return bucket.filter((s) => s.at >= from && s.at < to);
40	  }
41	
42	  /** Every series name currently holding at least one sample. */
43	  series(): string[] {
44	    return [...this.buckets.keys()].sort();
45	  }
46	
47	  /** Drop every sample older than `before`; returns how many were removed. */
48	  prune(before: number): number {
49	    let removed = 0;
50	    for (const [name, bucket] of this.buckets) {
51	      const keep = bucket.filter((s) => s.at >= before);
52	      removed += bucket.length - keep.length;
53	      if (keep.length === 0) {
54	        this.buckets.delete(name);
55	      } else {
56	        this.buckets.set(name, keep);
57	      }
58	    }
59	    return removed;
60	  }
61	
62	  size(): number {
63	    let total = 0;
64	    for (const bucket of this.buckets.values()) total += bucket.length;
65	    return total;
66	  }
67	}
68	
69	/** Binary search for the index at which `at` keeps `bucket` sorted. */
70	function insertionPoint(bucket: Sample[], at: number): number {
71	  let low = 0;
72	  let high = bucket.length;
73	  while (low < high) {
74	    const mid = (low + high) >>> 1;
75	    if (bucket[mid].at <= at) low = mid + 1;
76	    else high = mid;
77	  }
78	  return low;
79	}
