1	/**
2	 * A tiny method+path router over the store. Transport-agnostic on purpose —
3	 * `dispatch` takes strings and returns a plain object, so it is testable
4	 * without binding a socket.
5	 */
6	
7	import type { Clock } from "./clock.ts";
8	import type { Config } from "./config.ts";
9	import { IngestQueue, parseSample } from "./ingest.ts";
10	import { rollup } from "./rollup.ts";
11	import { MemoryStore } from "./store.ts";
12	import { formatSummary, summarize } from "./summary.ts";
13	import { ValidationError } from "./validate.ts";
14	
15	export interface Reply {
16	  status: number;
17	  body: string;
18	}
19	
20	export class Router {
21	  private readonly store: MemoryStore;
22	  private readonly queue: IngestQueue;
23	  private readonly config: Config;
24	  private readonly clock: Clock;
25	
26	  constructor(
27	    store: MemoryStore,
28	    queue: IngestQueue,
29	    config: Config,
30	    clock: Clock,
31	  ) {
32	    this.store = store;
33	    this.queue = queue;
34	    this.config = config;
35	    this.clock = clock;
36	  }
37	
38	  dispatch(method: string, path: string, body = ""): Reply {
39	    if (method === "POST" && path === "/samples") {
40	      return this.ingest(body);
41	    }
42	    if (method === "GET" && path === "/series") {
43	      return { status: 200, body: this.store.series().join("\n") };
44	    }
45	    if (method === "GET" && path.startsWith("/summary/")) {
46	      return this.summary(path.slice("/summary/".length));
47	    }
48	    return { status: 404, body: `no route for ${method} ${path}` };
49	  }
50	
51	  private ingest(body: string): Reply {
52	    const lines = body.split("\n").filter((line) => line.trim() !== "");
53	    let accepted = 0;
54	    try {
55	      for (const line of lines) {
56	        // Buffered, not stored: the queue is what absorbs a burst, and `tick()`
57	        // is what moves a sample into the store. A write that went straight to
58	        // the store would make the queue's overflow policy unreachable.
59	        this.queue.push(parseSample(line, this.clock.now()));
60	        accepted += 1;
61	      }
62	    } catch (error) {
63	      if (error instanceof ValidationError) {
64	        return { status: 400, body: `${error.message} (accepted ${accepted})` };
65	      }
66	      throw error;
67	    }
68	    return { status: 202, body: `accepted ${accepted}` };
69	  }
70	
71	  private summary(series: string): Reply {
72	    const windows = rollup(
73	      this.store,
74	      series,
75	      this.config.windowMs,
76	      this.clock.now(),
77	      this.config.retentionMs,
78	    );
79	    return { status: 200, body: formatSummary(summarize(windows, series)) };
80	  }
81	}
82	
83	export function createRouter(
84	  store: MemoryStore,
85	  queue: IngestQueue,
86	  config: Config,
87	  clock: Clock,
88	): Router {
89	  return new Router(store, queue, config, clock);
90	}
